/**
 * Monday.com Node - Version 2
 * Discriminator: resource=item, operation=archiveOrDeleteItem
 */


interface Credentials {
  mondayComApi: CredentialReference;
  mondayComOAuth2Api: CredentialReference;
}

/** Archive items (recoverable, the default) or permanently delete them — one picked item or up to 50 by ID */
export type MondayComV2ItemArchiveOrDeleteItemParams = {
  resource: 'item';
  operation: 'archiveOrDeleteItem';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * Whether to process one picked item or a list of item IDs
 * @default single
 */
    itemsMode?: 'multiple' | 'single';
/**
 * The board to operate on
 * @searchListMethod searchBoards
 * @displayOptions.hide { itemsMode: ["multiple"] }
 * @default {"mode":"list","value":""}
 */
    boardId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The item to operate on
 * @searchListMethod searchItems
 * @displayOptions.hide { itemsMode: ["multiple"] }
 * @default {"mode":"list","value":""}
 */
    itemId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Comma-separated IDs of the items to archive or delete (up to 50 per execution). Feed it from a Get Many operation with an expression.
 * @displayOptions.show { itemsMode: ["multiple"] }
 * @required when the displayOptions conditions above match
 */
    bulkItemIds?: string | Expression<string>;
/**
 * Whether to archive (recoverable) or permanently delete
 * @default archive
 */
    archiveOrDeleteAction?: 'archive' | 'delete' | Expression<string>;
};

export type MondayComV2ItemArchiveOrDeleteItemNode = {
  type: 'n8n-nodes-base.mondayCom';
  version: 2;
  config: NodeConfig<MondayComV2ItemArchiveOrDeleteItemParams> & { credentials?: Credentials };
};